irule_proxysend_77777777_7777_7777_7777_.iRule:
when SERVER_CONNECTED {
    if { [LB::server pool] eq "/flock/vip_11111111_1111_1111_1111_111111111111/pool_77777777_7777_7777_7777_777777777777" } {
        if { [IP::version] eq "6" } {
            set flock_pp_proto "TCP6"
        } else {
            set flock_pp_proto "TCP4"
        }
        TCP::respond "PROXY $flock_pp_proto [IP::client_addr] [IP::local_addr clientside] [TCP::client_port] [TCP::local_port clientside]\r\n"
    }
}

irule_sni_22222222_2222_2222_2222_222222.iRule:
when CLIENT_ACCEPTED {
    SSL::disable
    TCP::collect
}
when CLIENT_DATA {
    if { ![info exists flock_pp_done] } {
        set flock_pp_len 0
        if { [TCP::payload 6] eq "PROXY " } {
            set flock_pp_end [string first "\r\n" [TCP::payload]]
            if { $flock_pp_end < 0 } {
                TCP::collect
                return
            }
            set flock_pp_len [expr {$flock_pp_end + 2}]
        } elseif { [TCP::payload length] < 16 } {
            TCP::collect
            return
        } else {
            binary scan [TCP::payload 16] H24ccS flock_pp_sig flock_pp_ver flock_pp_fam flock_pp_addrlen
            if { $flock_pp_sig eq "0d0a0d0a000d0a515549540a" } {
                set flock_pp_len [expr {16 + ($flock_pp_addrlen & 0xffff)}]
                if { [TCP::payload length] < $flock_pp_len } {
                    TCP::collect
                    return
                }
            }
        }
        if { $flock_pp_len == 0 } {
            reject
            return
        }
        TCP::payload replace 0 $flock_pp_len ""
        set flock_pp_done 1
    }
    if { [TCP::payload length] < 5 } {
        TCP::collect
        return
    }
    binary scan [TCP::payload 5] cSS flock_tls_type flock_tls_version flock_tls_len
    set flock_tls_len [expr {$flock_tls_len & 0xffff}]
    set flock_sni ""
    if { $flock_tls_type == 22 } {
        if { [TCP::payload length] < [expr {$flock_tls_len + 5}] } {
            TCP::collect
            return
        }
        set flock_hello [TCP::payload [expr {$flock_tls_len + 5}]]
        set flock_off 43
        binary scan $flock_hello @${flock_off}c flock_len
        set flock_off [expr {$flock_off + 1 + ($flock_len & 0xff)}]
        binary scan $flock_hello @${flock_off}S flock_len
        set flock_off [expr {$flock_off + 2 + ($flock_len & 0xffff)}]
        binary scan $flock_hello @${flock_off}c flock_len
        set flock_off [expr {$flock_off + 1 + ($flock_len & 0xff)}]
        binary scan $flock_hello @${flock_off}S flock_ext_len
        set flock_off [expr {$flock_off + 2}]
        set flock_ext_end [expr {$flock_off + ($flock_ext_len & 0xffff)}]
        while { $flock_off + 4 <= $flock_ext_end } {
            binary scan $flock_hello @${flock_off}SS flock_ext_type flock_ext_size
            set flock_ext_size [expr {$flock_ext_size & 0xffff}]
            if { ($flock_ext_type & 0xffff) == 0 } {
                binary scan $flock_hello @[expr {$flock_off + 7}]S flock_name_len
                set flock_name_start [expr {$flock_off + 9}]
                set flock_name_end [expr {$flock_name_start + ($flock_name_len & 0xffff) - 1}]
                set flock_sni [string tolower [string range $flock_hello $flock_name_start $flock_name_end]]
                break
            }
            set flock_off [expr {$flock_off + 4 + $flock_ext_size}]
        }
    }
    if { $flock_sni eq "a.example.com" } {
        SSL::enable
        pool /flock/vip_11111111_1111_1111_1111_111111111111/pool_33333333_3333_3333_3333_333333333333
    } elseif { $flock_sni eq "db.example.com" } {
        pool /flock/vip_11111111_1111_1111_1111_111111111111/pool_77777777_7777_7777_7777_777777777777
    } elseif { [string match "*.example.com" $flock_sni] } {
        SSL::enable
        pool /flock/vip_11111111_1111_1111_1111_111111111111/pool_33333333_3333_3333_3333_333333333333
    } else {
        pool /flock/vip_11111111_1111_1111_1111_111111111111/pool_77777777_7777_7777_7777_777777777777
    }
    TCP::release
}
